head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pLIST_PROMT_SEQ = "";
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.trsIdx = "";
// 세션정보를 얻기위한 함수사용
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd"); // 오늘날짜
scwin.fn_SetPar;
scwin.gIntviewOrder;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.init();
        $c.elw.fn_searchCode();

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

        await scwin.listSync();
        if (scwin.pLIST_PROMT_SEQ === "" || dts_List.getCellData(1, "FORN_COM_YN") === "") chk_FORN_COM_YN.setValue(0);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06003.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    const parentWin = $c.frame.path("../");
    scwin.pLIST_PROMT_SEQ = parentWin.scwin.pLIST_PROMT_SEQ;
    scwin.log(scwin.pLIST_PROMT_SEQ);
    if (scwin.pLIST_PROMT_SEQ === undefined) {
        scwin.pLIST_PROMT_SEQ = "";
    }
    let YY_3 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 3;
    let YY_2 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 2;
    let YY_1 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 1;
    const YY = scwin.vCurDate.substr(0, 4);
    const YY1 = parseInt(scwin.vCurDate.substring(0, 4), 10) + parseInt(1, 10);
    const YY2 = parseInt(scwin.vCurDate.substring(0, 4), 10) + parseInt(2, 10);
    const YY3 = parseInt(scwin.vCurDate.substring(0, 4), 10) + parseInt(3, 10);
    const strCbd_SME_YN = YY_1 + "^" + YY_1 + "," + YY + "^" + YY + "," + YY1 + "^" + YY1 + "," + YY2 + "^" + YY2 + "," + YY3 + "^" + YY3 + ",9999^ 미정"; //	상장예정시기 setting(당해년도,Y+1,Y+2,Y+3,미정)
    cmb_LIST_SCHDL_TM_1.CBData = strCbd_SME_YN;
    cmb_LIST_SCHDL_TM_2.CBData = strCbd_SME_YN;
    cmb_LIST_SCHDL_TM_3.CBData = strCbd_SME_YN;
    cmb_LIST_SCHDL_TM_4.CBData = strCbd_SME_YN;
    cmb_LIST_SCHDL_TM_5.CBData = strCbd_SME_YN;
    txb_YY3.setValue(YY_3 + "년"); //	요약재무자료 Title(Y-2)
    txb_YY2.setValue(YY_2 + "년"); //	요약재무자료 Title(Y-1)
    txb_YY1.setValue(YY_1 + "년"); //	요약재무자료 Title(Y)
    panel_Item.show("");
};

///////// 3. 컴포넌트 이벤트 영역 /////////
