/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06003.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount > 0) {
            buttonSet.setUpdateStatus();
            btn_report.setBackgroundImage("../img/btn_print.gif");
            btn_report.setDisabled(false);
        } else {
            buttonSet.setInsertStatus();
            btn_report.setBackgroundImage("../img/btn_print_d.gif");
            btn_report.setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06003.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Info_OnLoadCompleted
 * @description dts_Info 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Info_OnLoadCompleted = async function(rowcount) {
    try {
        if (rowcount === 0) {
            await $c.win.alert("법인등록번호에 맞는 NICE 재무정보가 없습니다.");
            return;
        } else {
            cmb_EXT_AUDT_YN.setValue('Y');
        }
        if (dts_Info.getCellData(1, "COM_NM") !== "") txb_COM_NM.setValue(dts_Info.getCellData(1, "COM_NM"));
        if (dts_Info.getCellData(1, "FOUND_DD") !== "") edt_FOUND_DD.setValue(dts_Info.getCellData(1, "FOUND_DD"));
        if (dts_Info.getCellData(1, "FOUND_DD") !== "") edt_FOUND_DD.setValue(dts_Info.getCellData(1, "FOUND_DD"));
        if (dts_Info.getCellData(1, "CEO_NM1") !== "") txb_CEO_NM1.setValue(dts_Info.getCellData(1, "CEO_NM1"));
        if (dts_Info.getCellData(1, "IND_NM") !== "") txb_IND_NM.setValue(dts_Info.getCellData(1, "IND_NM"));
        if (dts_Info.getCellData(1, "MAJ_PROD_NM") !== "") txb_MAJ_PROD_NM.setValue(dts_Info.getCellData(1, "MAJ_PROD_NM"));
        if (dts_Info.getCellData(1, "LOC_ZIPCD") !== "") txb_LOC_ZIPCD.setValue(dts_Info.getCellData(1, "LOC_ZIPCD"));
        if (dts_Info.getCellData(1, "LOC_ADDR") !== "") txb_LOC_ADDR.setValue(dts_Info.getCellData(1, "LOC_ADDR"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06003.dts_Info_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_financeInfo_OnLoadCompleted
 * @description dts_financeInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_financeInfo_OnLoadCompleted = function(rowcount) {
    try {
        let YY_3 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 3;
        let YY_2 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 2;
        let YY_1 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 1;
        for (let i = 1; i <= rowcount; i++) {
            if (YY_3 === dts_financeInfo.getCellData(i, "FISCAL_YYYY")) {
                edt_SALES_2.setValue(dts_financeInfo.getCellData(i, "SALES"));
                edt_BZ_PROFT_AMT_2.setValue(dts_financeInfo.getCellData(i, "BZ_PROFT_AMT"));
                edt_NETINCM_AMT_2.setValue(dts_financeInfo.getCellData(i, "NETINCM_AMT"));
                edt_ASST_TOTAMT_2.setValue(dts_financeInfo.getCellData(i, "ASST_TOTAMT"));
                edt_DEBT_TOTAMT_2.setValue(dts_financeInfo.getCellData(i, "DEBT_TOTAMT"));
                edt_CAP_TOTAMT_2.setValue(dts_financeInfo.getCellData(i, "CAP_TOTAMT"));
            } else if (YY_2 === dts_financeInfo.getCellData(i, "FISCAL_YYYY")) {
                edt_SALES_1.setValue(dts_financeInfo.getCellData(i, "SALES"));
                edt_BZ_PROFT_AMT_1.setValue(dts_financeInfo.getCellData(i, "BZ_PROFT_AMT"));
                edt_NETINCM_AMT_1.setValue(dts_financeInfo.getCellData(i, "NETINCM_AMT"));
                edt_ASST_TOTAMT_1.setValue(dts_financeInfo.getCellData(i, "ASST_TOTAMT"));
                edt_DEBT_TOTAMT_1.setValue(dts_financeInfo.getCellData(i, "DEBT_TOTAMT"));
                edt_CAP_TOTAMT_1.setValue(dts_financeInfo.getCellData(i, "CAP_TOTAMT"));
            } else if (YY_1 === dts_financeInfo.getCellData(i, "FISCAL_YYYY")) {
                edt_SALES_0.setValue(dts_financeInfo.getCellData(i, "SALES"));
                edt_BZ_PROFT_AMT_0.setValue(dts_financeInfo.getCellData(i, "BZ_PROFT_AMT"));
                edt_NETINCM_AMT_0.setValue(dts_financeInfo.getCellData(i, "NETINCM_AMT"));
                edt_ASST_TOTAMT_0.setValue(dts_financeInfo.getCellData(i, "ASST_TOTAMT"));
                edt_DEBT_TOTAMT_0.setValue(dts_financeInfo.getCellData(i, "DEBT_TOTAMT"));
                edt_CAP_TOTAMT_0.setValue(dts_financeInfo.getCellData(i, "CAP_TOTAMT"));
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06003.dts_financeInfo_OnLoadCompleted" });
    }
};

/**
