};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        if (scwin.trsIdx === TR_JOB_DELETE) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
            scwin.parentRefresh();
            await $c.win.closePopup();
        } else {
            await scwin.listGenenal();
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06003.trs_Save_OnSuccess" });
    }
};

