/**
 * @method
 * @name searchCode
 * @description 공통코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    let curYY = parseInt(scwin.vCurDate.substr(0, 4));
    let strCodeCnt = "^ ,";
    for (i = 0; i < 10; i++) {
        strCodeCnt += curYY + "^" + curYY + ",";
        curYY = curYY - 1;
    }
    gcurYY = curYY;
    cmb_CEO_CRS_STRT_DD.CBData = strCodeCnt;
    cmb_LIST_PROFS_CRS_STRT_DD.CBData = strCodeCnt;
    /*
    	03270	면담방법코드(1:방문,2:유선,3:서면,4:기타)
     */
    let arrCid = [{
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD_1"
    }, {
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD_2"
    }, {
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD_3"
    }, {
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD_4"
    }, {
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD_5"
    }, {
        cid: "LIST_PROPEL_STEP_TP_CD",
        cnm: "cmb_LIST_PROPEL_STEP_TP_CD"
    }, {
        cid: "VENT_ADM_INST_CD",
        cnm: "cmb_REL_INST_NM"
    }];
    let objCod;
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='INTVIEW_ACTIV_CD','INTVIEW_ACTIV_CD','INTVIEW_ACTIV_CD','INTVIEW_ACTIV_CD','INTVIEW_ACTIV_CD','LIST_PROPEL_STEP_TP_CD','VENT_ADM_INST_CD'";
    const sbmOptions = {
        id : "sbm_dts_Code",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Code=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^' '";
        for (j = 1; j <= dts_Code.getRowCount(); j++) {
            if (dts_Code.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }

    // 담당자
    const sbmOptions2 = {
        id : "sbm_dts_EmpNo",
        action : "/ListPromtHistMgt.do",
        ref : "",
        target : "dts_EmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    strCbd = "";
    if (dts_EmpNo.getRowCount() > 0) {
        strCbd = "^선택";
        for (let i = 1; i <= dts_EmpNo.getRowCount(); i++) {
            strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_EmpNo.getCellData(i, "EMP_NO") + "^" + dts_EmpNo.getCellData(i, "DEP_EMP_NM");
        }

        // 1차
        cmb_INTVIEW_CHRG_EMP_NO_10.CBData = strCbd; //	KRX 담당자
        cmb_INTVIEW_CHRG_EMP_NO_11.CBData = strCbd; //	KRX 담당자2
        cmb_INTVIEW_CHRG_EMP_NO_12.CBData = strCbd; //	KRX 담당자3

        // 2차
        cmb_INTVIEW_CHRG_EMP_NO_20.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_21.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_22.CBData = strCbd;

        // 3차
        cmb_INTVIEW_CHRG_EMP_NO_30.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_31.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_32.CBData = strCbd;

        // 4차
        cmb_INTVIEW_CHRG_EMP_NO_40.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_41.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_42.CBData = strCbd;

        // 5차
        cmb_INTVIEW_CHRG_EMP_NO_50.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_51.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_52.CBData = strCbd;
    }

    //    주관사명
    const sbmOptions3 = {
        id : "sbm_dts_MajagntInst",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_MajagntInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_MajagntInst.setBroadcast(false);
    for (let k = 1; k <= dts_MajagntInst.getRowCount(); k++) {
        if (dts_MajagntInst.getCellData(k, "TEXT") === "") {
            // 널값은 삭제
            dts_MajagntInst.removeRow(k);
        }
    }
    dts_MajagntInst.setBroadcast(true, true);
};

