    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 면담개요조회
    url += "&inputMessageId=LISTPROMTINTVIEWDTL_INOUT&outputMessageId=LISTPROMTINTVIEWDTL_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    const sbmOptions4 = {
        id : "sbm_dts_IntviewDtlList",
        action : "/ListPromtHistMgt.do",
        ref : "",
        target : "dts_IntviewDtlList=body.content",
