    };

    const sbmRtn6 = await $c.sbm.executeDynamic(sbmOptions6);
    // TODO Stage2: sbmRtn6 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    await scwin.setHeader();
    if (dts_List.getRowCount() < 1) {
        dts_List.insertRow();
    }
    if (dts_IntviewPrnList.getRowCount() < 1) {
        dts_IntviewPrnList.insertRow();
    }
    if (dts_IntviewDtlList.getRowCount() < 1) {
        dts_IntviewDtlList.insertRow();
    } else {
        if (dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_5") !== '' && $c.ut.isDate(dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_5"))) {
            MaxTab_01.setSelectedTabIndex(5);
        } else if (dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_4") !== '' && $c.ut.isDate(dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_4"))) {
            MaxTab_01.setSelectedTabIndex(4);
        } else if (dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_3") !== '' && $c.ut.isDate(dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_3"))) {
            MaxTab_01.setSelectedTabIndex(3);
