/**
 * @method
 * @name checkForm
 * @description 입력값 Check
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (!$c.cp.isModified(dts_List) && !$c.cp.isModified(dts_IntviewDtlList) &&
        !$c.cp.isModified(dts_IntviewPrnList) && !$c.cp.isModified(dts_YearFnc) &&
        !$c.cp.isModified(dts_YearFncTotal) && !$c.cp.isModified(dts_fileList) &&
        !$c.cp.isModified(dts_Invst)) {
        await $c.win.alert(scwin.MGS_NO_UPDT);
        return false;
    }
    if (txb_COM_NM.getValue() === "") {
        await $c.win.alert("[회사명]을  입력하세요.");
        txb_COM_NM.focus();
        return false;
    }
    if (dts_List.getCellData(1, "CORP_REG_NO") === "") {
        await $c.win.alert("[법인등록번호]을  입력하세요.");
        txb_CORP_REG_NO.focus();
        return false;
    }
    if (dts_List.getCellData(1, "CORP_REG_NO").length !== 13) {
        await $c.win.alert("[법인등록번호] 13자리가 아닙니다.");
        txb_CORP_REG_NO.focus();
        return false;
    }

    /*if(getObjectValue(txb_LOC_ADDR) == "") {
    	alert("[소재지을  입력하세요.");
    	txb_LOC_ADDR.focus();
    	return false;
    }*/

    return true;
};

