/**
 * @method
 * @name setInvstDataSet
 * @description set Invst Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.setInvstDataSet = function() {
    dts_InvstChange.setBroadcast(false);
    for (let i = 1; i <= 7; i++) {
        dts_InvstChange.insertRow();
        dts_InvstChange.setCellData(dts_InvstChange.getRowPosition(), "LIST_PROMT_SEQ", scwin.pLIST_PROMT_SEQ);
        dts_InvstChange.setCellData(dts_InvstChange.getRowPosition(), "COM_INVST_TP_CD", dts_Invst.getCellData(1, "COM_INVST_TP_CD_" + i));
        dts_InvstChange.setCellData(dts_InvstChange.getRowPosition(), "MISC_INVST_TP_NM", dts_Invst.getCellData(1, "MISC_INVST_TP_NM_" + i));
        dts_InvstChange.setCellData(dts_InvstChange.getRowPosition(), "INVST_DD", dts_Invst.getCellData(1, "INVST_DD_" + i));
        dts_InvstChange.setCellData(dts_InvstChange.getRowPosition(), "INVST_AMT", dts_Invst.getCellData(1, "INVST_AMT_" + i));
        dts_InvstChange.setCellData(dts_InvstChange.getRowPosition(), "INVST_NM", dts_Invst.getCellData(1, "INVST_NM_" + i));
    }
    dts_InvstChange.setBroadcast(true, true);
};

/**
 * @method
 * @name setInviewPrnDataSet
 * @description 면담대상자 데이터셋
 * @returns {void}
 * @hidden N
 */
scwin.setInviewPrnDataSet = function() {
    if (dts_IntviewPrnList.getRowCount() > 0) {
        //    1차 100,101,102    2차:200,201,202 ...
        dts_IntviewPrnChange.setBroadcast(false);
        for (let i = 1; i <= 5; i++) {
            for (let j = 0; j <= 2; j++) {
                dts_IntviewPrnChange.insertRow();
                dts_IntviewPrnChange.setCellData(dts_IntviewPrnChange.getRowPosition(), "LIST_PROMT_SEQ", dts_List.getCellData(1, "LIST_PROMT_SEQ"));
                dts_IntviewPrnChange.setCellData(dts_IntviewPrnChange.getRowPosition(), "SEQ", i + '0' + j);
                dts_IntviewPrnChange.setCellData(dts_IntviewPrnChange.getRowPosition(), "UDGOCONSULTR_NM", dts_IntviewPrnList.getCellData(1, "UDGOCONSULTR_NM_" + i + '' + j));
                dts_IntviewPrnChange.setCellData(dts_IntviewPrnChange.getRowPosition(), "UDGOCONSULTR_JOBPOS_NM", dts_IntviewPrnList.getCellData(1, "UDGOCONSULTR_JOBPOS_NM_" + i + '' + j));
