/**
 * @method
 * @name setGeneralPrint
 * @description set General Print 처리
 * @returns {void}
 * @hidden N
 */
scwin.setGeneralPrint = function() {
    dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "COM_NM", dts_List.getCellData(1, "COM_NM"));
    dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "RPT_DD", scwin.vCurDate.substr(2, 2) + "." + scwin.vCurDate.substr(4, 2) + "." + scwin.vCurDate.substr(6, 2));
    dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "LOC_ADDR", dts_List.getCellData(1, "LOC_ADDR"));
    dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "FOUND_DD", dts_List.getCellData(1, "FOUND_DD").substr(2, 2) + "." + dts_List.getCellData(1, "FOUND_DD").substr(4, 2) + "." + dts_List.getCellData(1, "FOUND_DD").substr(6, 2));
    dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "CEO_NM", dts_List.getCellData(1, "CEO_NM1"));
    dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "MAJSHRHD_CONTN", dts_List.getCellData(1, "MAJSHRHD_CONTN"));
    dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "MAJ_PROD_NM", dts_List.getCellData(1, "MAJ_PROD_NM"));
    const arr = new Array();
    let idx = 0;
    for (let i = 1; i <= 7; i++) {
        if (dts_Invst.getCellData(1, "INVST_DD_" + i) !== "") {
            arr[idx++] = dts_Invst.getCellData(1, "INVST_DD_" + i) + "^" + dts_Invst.getCellData(1, "INVST_NM_" + i);
        }
    }
    arr.sort();
    let InvstNm = "";
    for (let i = arr.length - 1; i >= 0; i--) {
        const Invst = arr[i].split('^');
        if (i !== 0 && Invst[1] !== "") {
            Invst[1] += ", ";
        }
        InvstNm += Invst[1];
    }
    dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "INVST_NM", InvstNm);
};

